export const TWEMOJI_ICON_IDS = Object.freeze(Object.values(ICON_IDS));

export function iconIdForEmoji(emoji: string): string {
  return ICON_IDS[emoji] ?? ICON_IDS["❓"]!;
}

export function twemojiSymbolDefs(iconIds: Iterable<string>): string {
  const unique = [...new Set(iconIds)].sort();
  return `<defs data-twemoji-version="${TWEMOJI_VERSION}">${unique.map((id) => SYMBOLS[id] ?? "").join("")}</defs>`;
}

export function twemojiUseMarkup(iconId: string, x: number, y: number, size: number, className = "emoji-icon"): string {
  const safeId = SYMBOLS[iconId] ? iconId : ICON_IDS["❓"]!;
  return `<svg class="${className}" x="${x}" y="${y}" width="${size}" height="${size}" viewBox="0 0 36 36" aria-hidden="true"><use href="#${safeId}"/></svg>`;
}
